package library

import (
	"fmt"
	"testing"

	"github.com/moodiness/polyfin/internal/addons"
	"github.com/moodiness/polyfin/internal/stremio"
)

// A new movie library, generated by default, listed before any of its
// titles were read, has no image; once its first page was read, as an app
// opening it reads it, the next listing shows its image, with no time
// passing in between.
func TestNewLibrariesShowTheirImageOnceTheirTitlesAreRead(t *testing.T) {
	t.Parallel()
	e := newEnv(t)
	e.install(addons.Shared(), &fakeAddon{
		manifest: stremio.Manifest{ID: "a", Name: "A", Version: "1", Types: []string{"movie"},
			Resources: []stremio.Resource{{Name: "catalog"}}, Catalogs: []stremio.Catalog{{Type: "movie", ID: "top", Name: "Top"}}},
		catalogs: map[string][]stremio.Meta{"movie/top": titles("movie", 8)},
	})
	if image := e.library(e.admin, "Top").Images.Primary; image != "" {
		t.Fatalf("before its titles were read: %q", image)
	}
	if got := e.children(e.admin, "Top", 0, 10).Items; len(got) != 8 {
		t.Fatalf("the library's titles: %v", names(got))
	}
	if image := e.library(e.admin, "Top").Images.Primary; image == "" {
		t.Error("once its titles were read, the library still has no image")
	}
}

// An item whose first titles were not known looks again once an addon's
// answer is kept, and only then; one whose titles were known and gave no
// image keeps that for generatedCheck, whatever is kept meanwhile.
func TestGeneratedImagesNotFoundLookAgainOnlyWhenUnknown(t *testing.T) {
	t.Parallel()
	e := newEnv(t)
	for _, known := range []bool{false, true} {
		id := itemID(fmt.Sprint("item known ", known))
		asked := 0
		find := func() ([]candidate, bool, bool) { asked++; return nil, known, false }
		for range 2 {
			if _, ok := e.service.generatedChoiceOf(t.Context(), id, "Item", find); ok {
				t.Fatalf("known %t: an image without titles", known)
			}
		}
		e.service.generated.kept.Add(1)
		e.service.generatedChoiceOf(t.Context(), id, "Item", find)
		if want := map[bool]int{false: 2, true: 1}[known]; asked != want {
			t.Errorf("known %t: titles read %d times, want %d", known, asked, want)
		}
	}
}
